    "profileText": "{\n  \"name\": \"aidlc-composer-agent\",\n  \"description\": \"AI-DLC Composer Agent - delegation target for composing a workflow plan (front, report, or in-flight). Proposes the EXECUTE/SKIP grid and its settings; the engine applies the approved plan and saves it as a scope only when the person asks.\",\n  \"prompt\": \"file://aidlc-composer-agent.md\",\n  \"includeMcpJson\": true,\n  \"tools\": [\n    \"fs_read\",\n    \"fs_write\",\n    \"execute_bash\",\n    \"thinking\",\n    \"@context7\",\n    \"@aws-mcp\",\n    \"@aws-pricing\",\n    \"@aws-iac\",\n    \"@aws-serverless\"\n  ],\n  \"allowedTools\": [\n    \"fs_read\",\n    \"thinking\"\n  ],\n  \"toolsSettings\": {\n    \"execute_bash\": {\n      \"allowedCommands\": [\n        \"bun (run )?[\\\"']?\\\\.kiro/tools/[A-Za-z0-9._-]+\\\\.ts[\\\"']?( .*)?\"\n      ],\n      \"deniedCommands\": [\n        \"([^\\\\s]*/)?rm( [^\\\\s]+)* -[A-Za-z]*[rR][A-Za-z]*( .*)?\",\n        \"([^\\\\s]*/)?rm( [^\\\\s]+)* --recursive( .*)?\",\n        \"([^\\\\s]*/)?git( -[^\\\\s]+( (\\\"[^\\\"]*\\\"|'[^']*'|[^\\\\s]+))?)* push( .*)?\"\n      ]\n    },\n    \"fs_write\": {\n      \"allowedPaths\": [\n        \"aidlc/spaces/*/intents/.aidlc-engine/composer-proposal.json\"\n      ]\n    }\n  },\n  \"resources\": [\n    \"file://.kiro/agents/aidlc-composer-agent.md\",\n    \"file://.kiro/scopes/*.md\",\n    \"file://.kiro/knowledge/aidlc-shared/*.md\",\n    \"file://aidlc/spaces/default/memory/**/*.md\"\n  ],\n  \"hooks\": {\n    \"preToolUse\": [\n      {\n        \"matcher\": \"execute_bash\",\n        \"command\": \"{{INVOKE}} engine adapter kiro state-transition-guard aidlc-composer-agent\",\n        \"timeout_ms\": 1800000\n      },\n      {\n        \"matcher\": \"fs_write\",\n        \"command\": \"{{INVOKE}} engine adapter kiro review-freeze\",\n        \"timeout_ms\": 1800000\n      },\n      {\n        \"matcher\": \"execute_bash\",\n        \"command\": \"{{INVOKE}} engine adapter kiro review-freeze\",\n        \"timeout_ms\": 1800000\n      },\n      {\n        \"matcher\": \"fs_write\",\n        \"command\": \"{{INVOKE}} engine adapter kiro plan-approval-guard\",\n        \"timeout_ms\": 1800000\n      },\n      {\n        \"matcher\": \"execute_bash\",\n        \"command\": \"{{INVOKE}} engine adapter kiro plan-approval-guard\",\n        \"timeout_ms\": 1800000\n      }\n    ],\n    \"postToolUse\": [\n      {\n        \"matcher\": \"fs_write\",\n        \"command\": \"{{INVOKE}} engine adapter kiro audit-and-sensors\",\n        \"timeout_ms\": 3600000\n      }\n    ]\n  }\n}\n",
